def raw_exercise():
    L = ['مشق', '']
    L += [f'{n}۔ {q}' for n, (q, _) in zip(['۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸'], QS[:8])]
    L += ['۹۔ درست جواب کا انتخاب کریں۔']
    L += [f'({r}) {q} ' + ' '.join(f'({l}) {o}' for l, o in zip(L4, opts)) for r, (q, opts, _) in zip(['i', 'ii', 'iii'], MCQ)]
    L += ['', ACTIVITY]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = []
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['textbookMcqs'] = [dict(question=q, options=o, correct=c) for q, o, c in MCQ]
    ex['activity'] = ACTIVITY.split(': ', 1)[1]
    ex.pop('teacherInstructions', None)
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'
    ex.pop('contextualTashreeh', None)


